"""Local prompt/response inspector, served by the existing AI service."""
PAGE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ESSAIM · LLM Inspector</title>
<style>
:root{color-scheme:dark;font:15px system-ui;background:#10191c;color:#e7f0ed}*{box-sizing:border-box}body{margin:0;padding:24px}h1{margin:0;font-size:26px}header{display:flex;justify-content:space-between;align-items:center}small,.muted{color:#a5b8b3}button,input,select{font:inherit;background:#1b2b2e;color:inherit;border:1px solid #45605b;border-radius:7px;padding:8px}button{cursor:pointer}#models{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}.card,section{background:#172528;border:1px solid #314b47;border-radius:12px;padding:16px}.card h2{font-size:18px;margin:0 0 10px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.workspace{display:grid;grid-template-columns:minmax(260px,1fr) minmax(400px,2fr);gap:16px}#list{max-height:72vh;overflow:auto}#list button{display:block;width:100%;text-align:left;margin:0 0 8px;white-space:pre-wrap}#list button.selected{border-color:#9be3c5;background:#24453d}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#10191c;padding:14px;border-radius:8px;font:13px/1.5 ui-monospace,monospace;max-height:48vh;overflow:auto}summary{cursor:pointer;padding:8px 0;font-weight:600}.good{color:#9be3c5}.bad{color:#ffb6a6}#connection{white-space:pre-wrap}#details h2{font-size:19px;margin-top:0}@media(max-width:850px){#models,.workspace{grid-template-columns:1fr}body{padding:14px}}
</style>
<header><div><h1>ESSAIM / LLM Inspector</h1><small>Shared models · live inference attempts · refreshes every 2 seconds</small></div><button id="pause">Pause refresh</button></header>
<p id="connection" role="status">Connecting…</p><div id="models"></div>
<div class="filters"><select id="model"><option value="">All models</option><option>qwen2.5:0.5b</option><option>llama3.2:1b</option><option>qwen2.5:1.5b</option></select><input id="agent" aria-label="Agent ID" placeholder="Agent, e.g. A001"><input id="run" aria-label="Run ID" placeholder="Run ID"><button id="filter">Apply filters</button><button id="download" disabled>Download selected JSON</button></div>
<div class="workspace"><section><h2>Recent attempts</h2><small>Latest 300 attempts retained here. Full history is archived as JSONL. VALID means backend-valid, not proof Godot applied it.</small><div id="list"></div></section><section id="details"><h2>Select an attempt</h2><p class="muted">Run Godot, start the simulation and launch an evacuation to see real prompts and answers.</p></section></div>
<script>
let paused=false,selected=null,current=null,busy=false;
const $=id=>document.getElementById(id), fmt=(n,d=2)=>Number(n||0).toFixed(d);
function node(tag,text,parent){const el=document.createElement(tag);el.textContent=text;parent.appendChild(el);return el}
async function get(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);return r.json()}
async function detail(){if(!selected)return;current=await get('/traces/'+encodeURIComponent(selected));const box=$('details');box.replaceChildren();node('h2',current.model+' / '+current.agent_id,box);node('p',`${current.status} · attempt ${current.attempt} · ${fmt(current.latency_seconds)}s · ${current.started_at}`,box);node('p',`Run ${current.run_id} · request ${current.request_id}`,box);for(const [title,value] of [['System prompt',current.system_prompt],['Agent prompt sent',current.prompt],['Raw LLM answer',current.raw_answer??'Awaiting answer…'],['Validation error',current.error||'None'],['Validated decision',current.decision],['Exact request payload',current.request_payload],['Full Ollama response (tokens and timings)',current.raw_response]]){const group=node('details','',box);group.open=['Agent prompt sent','Raw LLM answer','Validation error'].includes(title);node('summary',title,group);node('pre',typeof value==='string'?value:JSON.stringify(value??null,null,2),group)}$('download').disabled=false}
async function refresh(){if(paused||busy)return;busy=true;try{const params=new URLSearchParams();for(const key of ['model','agent','run'])if($(key).value.trim())params.set(key,$(key).value.trim());const [health,result]=await Promise.all([get('/health'),get('/traces?'+params)]);$('connection').textContent=`${health.status} · mode ${health.mode} · active ${health.active}/${health.concurrency} · queued ${health.pending} · model VRAM peak ${fmt(health.peak_vram_bytes/1e9)} GB`+(health.trace_write_error?'\nTrace write error: '+health.trace_write_error:'');$('models').replaceChildren();for(const [model,stats]of Object.entries(health.per_model)){const card=node('div','',$('models'));card.className='card';node('h2',model,card);node('p',`Active ${health.active_by_model?.[model]||0} · requests ${stats.requests} · completed ${stats.completed}`,card);node('p',`${fmt(stats.average_request_latency_seconds)}s/request · ${fmt(stats.tokens_per_second,1)} tokens/s`,card);node('p',`Invalid outputs ${stats.invalid_responses} · fallbacks ${stats.fallbacks}`,card);node('small',health.residency[model]?'Resident · '+fmt(health.residency[model].size_vram/1e9)+' GB VRAM':'Not reported resident',card)}$('list').replaceChildren();if(!result.items.length)node('p','No matching attempts yet.',$('list'));for(const item of result.items){const b=node('button',`${item.model} / ${item.agent_id}\n${item.status} · attempt ${item.attempt} · ${fmt(item.latency_seconds)}s\n${item.started_at}`,$('list'));if(item.trace_id===selected)b.className='selected';b.onclick=async()=>{selected=item.trace_id;try{await detail()}catch(e){$('connection').textContent=e.message}}}if(selected)await detail()}catch(e){$('connection').textContent='Inspector connection error: '+e.message}finally{busy=false}}
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume refresh':'Pause refresh';if(!paused)refresh()};$('filter').onclick=()=>{selected=null;current=null;$('details').replaceChildren();$('download').disabled=true;refresh()};$('model').onchange=$('filter').onclick;$('download').onclick=()=>{if(!current)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'}));a.download=current.trace_id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};refresh();setInterval(refresh,2000);
</script></html>'''
